// ContextManager: minimal contract for budgeting + compaction + caching.
export interface MessageSlot {
  role: 'system' | 'tools' | 'history' | 'retrieved' | 'current';
  content: string | object;
  tokenEstimate: number;
  cacheable: boolean;
}

export interface ContextManager {
  /** Add a slot to the pending turn. */
  add(slot: MessageSlot): void;
  /** Pack into an Anthropic Messages API payload, applying budget + compaction + cache markers. */
  pack(budgetTokens: number): {
    system: { type: 'text'; text: string; cache_control?: { type: 'ephemeral' } }[];
    messages: { role: 'user' | 'assistant'; content: unknown }[];
    cacheBreakpoints: number;
  };
  /** Run compaction policy. Returns tokens freed. */
  compact(strategy: 'summarize-old' | 'drop-old' | 'structural'): Promise<number>;
  /** Telemetry. */
  telemetry(): { perSlot: Record<string, number>; total: number };
}

// Reference compaction triggers.
export const COMPACTION_TRIGGERS = {
  /** Compact when input would exceed 60% of context window. */
  byBudget: (currentTokens: number, windowTokens: number) => currentTokens / windowTokens > 0.6,
  /** Compact every N turns regardless. */
  byTurns: (turnNumber: number, every = 10) => turnNumber > 0 && turnNumber % every === 0,
  /** Compact when scratchpad alone exceeds K. */
  byScratchpad: (scratchpadTokens: number, max = 3000) => scratchpadTokens > max,
};
